__d(function(e,t,n,a,o,s,r){o.exports={"Calendar.basic":{code:"import { useState } from 'react';\nimport { Block, Text } from '@plocks/ui';\nimport { Calendar } from '@plocks/dates';\n\nconst formatter = new Intl.DateTimeFormat('en-US', { dateStyle: 'medium' });\n\nexport function Demo() {\n  const [selectedDate, setSelectedDate] = useState<Date | null>(new Date());\n\n  return (\n    <Block fullWidth>\n      <Calendar\n        value={selectedDate}\n        onChange={(date) => setSelectedDate(date as Date | null)}\n        highlightToday\n      />\n      <Text size=\"sm\" c=\"secondary\">\n        Selected date: {selectedDate ? formatter.format(selectedDate) : 'none'}\n      </Text>\n    </Block>\n  );\n}\n",hash:"ba01ffcfcd79c9d526cee16cdd475efec82fefa6ac8ea4a8f374fdc843812eb6",importPath:"../../../../packages/dates/src/components/Calendar/demos/basic",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/dates/src/components/Calendar/demos/basic/index.tsx"},"Calendar.constrained":{code:"import { useMemo, useState } from 'react';\nimport { Block, Text } from '@plocks/ui';\nimport { Calendar } from '@plocks/dates';\n\nconst monthFormatter = new Intl.DateTimeFormat('en-US', { month: 'long', year: 'numeric' });\nconst dateFormatter = new Intl.DateTimeFormat('en-US', { dateStyle: 'medium' });\n\nexport function Demo() {\n  const [selectedDate, setSelectedDate] = useState<Date | null>(new Date());\n\n  const { minDate, maxDate, monthLabel } = useMemo(() => {\n    const today = new Date();\n    const start = new Date(today.getFullYear(), today.getMonth(), 1);\n    const end = new Date(today.getFullYear(), today.getMonth() + 1, 0);\n    return { minDate: start, maxDate: end, monthLabel: monthFormatter.format(start) };\n  }, []);\n\n  return (\n    <Block fullWidth>\n      <Calendar\n        value={selectedDate}\n        onChange={(date) => setSelectedDate(date as Date | null)}\n        minDate={minDate}\n        maxDate={maxDate}\n        highlightToday\n      />\n      <Text size=\"sm\" c=\"secondary\">\n        Selected date: {selectedDate ? dateFormatter.format(selectedDate) : 'none'}\n      </Text>\n      <Text size=\"xs\" c=\"secondary\">\n        Only dates in {monthLabel} are enabled.\n      </Text>\n    </Block>\n  );\n}",hash:"b7c0eb316313c0de8dab48ac12ee6eff9933ba4dc27cf0108cf5e6ad3820778a",importPath:"../../../../packages/dates/src/components/Calendar/demos/constrained",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/dates/src/components/Calendar/demos/constrained/index.tsx"},"Calendar.multiple":{code:"import { useMemo, useState } from 'react';\nimport { Block, Text } from '@plocks/ui';\nimport { Calendar } from '@plocks/dates';\n\nconst formatter = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' });\n\nexport function Demo() {\n  const [selectedDates, setSelectedDates] = useState<Date[]>([]);\n\n  const summary = useMemo(() => {\n    if (selectedDates.length === 0) return 'No dates picked yet.';\n    if (selectedDates.length === 1) {\n      return `1 date picked: ${formatter.format(selectedDates[0])}`;\n    }\n    return `${selectedDates.length} dates picked: ${selectedDates.map((date) => formatter.format(date)).join(', ')}`;\n  }, [selectedDates]);\n\n  return (\n    <Block fullWidth>\n      <Calendar\n        type=\"multiple\"\n        value={selectedDates}\n        onChange={(dates) => setSelectedDates(dates as Date[])}\n        highlightToday\n      />\n      <Text size=\"sm\" c=\"secondary\">\n        {summary}\n      </Text>\n    </Block>\n  );\n}",hash:"bf8ccdcadd606b9a43ef0f5283f290eb017b8698be1c49a2f60ac088c466ed17",importPath:"../../../../packages/dates/src/components/Calendar/demos/multiple",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/dates/src/components/Calendar/demos/multiple/index.tsx"},"Calendar.range":{code:"import { useMemo, useState } from 'react';\nimport { Block, Text } from '@plocks/ui';\nimport { Calendar } from '@plocks/dates';\n\nconst formatter = new Intl.DateTimeFormat('en-US', { dateStyle: 'medium' });\n\nexport function Demo() {\n  const [selectedRange, setSelectedRange] = useState<[Date | null, Date | null]>([null, null]);\n\n  const summary = useMemo(() => {\n    const [start, end] = selectedRange;\n    if (!start) {\n      return 'No dates selected yet.';\n    }\n    if (!end) {\n      return `Start date chosen: ${formatter.format(start)} \u2014 pick an end date.`;\n    }\n    return `${formatter.format(start)} \u2192 ${formatter.format(end)}`;\n  }, [selectedRange]);\n\n  return (\n    <Block fullWidth>\n      <Calendar\n        type=\"range\"\n        value={selectedRange}\n        onChange={(range) => setSelectedRange(range as [Date | null, Date | null])}\n        highlightToday\n      />\n      <Text size=\"sm\" c=\"secondary\">\n        {summary}\n      </Text>\n    </Block>\n  );\n}",hash:"abc96bce3b436c802c3b59e2e13dedb0539ac600c76da06755a7748dcf1e4813",importPath:"../../../../packages/dates/src/components/Calendar/demos/range",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/dates/src/components/Calendar/demos/range/index.tsx"}}},3561,[]);
