__d(function(e,o,n,l,t,c,r){t.exports={"ColorSwatch.advanced":{code:"import { useState } from 'react';\nimport { Flex, Text, ColorSwatch } from '@plocks/ui';\n\nexport function Demo() {\n  const [selectedColor, setSelectedColor] = useState<string>('#E74C3C');\n\n  return (\n    <Flex direction=\"column\" gap={20} p={16} >\n      <Flex direction=\"column\" gap={8}>\n        <Text size=\"sm\">Grayscale palette:</Text>\n        <Flex direction=\"row\" gap={2}>\n          {[\n            '#000000', '#1a1a1a', '#333333', '#4d4d4d', '#666666',\n            '#808080', '#999999', '#b3b3b3', '#cccccc', '#e6e6e6', '#ffffff'\n          ].map(color => (\n            <ColorSwatch\n              key={color}\n              color={color}\n              borderRadius={2}\n              selected={selectedColor === color}\n              onPress={() => setSelectedColor(color)}\n            />\n          ))}\n        </Flex>\n      </Flex>\n\n      <Flex direction=\"column\" gap={8}>\n        <Text size=\"sm\">Large display swatch:</Text>\n        <Flex direction=\"row\" align=\"center\" gap={16}>\n          <ColorSwatch \n            color={selectedColor} \n            size={80} \n            borderRadius={8}\n            showCheckmark={false}\n          />\n          <Flex direction=\"column\" gap={4}>\n            <Text fw=\"semibold\">{selectedColor}</Text>\n            <Text size=\"xs\" c=\"secondary\">Click any swatch above to change</Text>\n          </Flex>\n        </Flex>\n      </Flex>\n    </Flex>\n  );\n}",hash:"5eb773e086249efba3e5d21f9ddd7d93ec4ba5dad9705154af7e5850c987b835",importPath:"../../../../packages/ui/src/components/ColorSwatch/demos/advanced",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/ColorSwatch/demos/advanced/index.tsx"},"ColorSwatch.basic":{code:"import React, { useState } from 'react';\nimport { Flex, Text, ColorSwatch } from '@plocks/ui';\n\nconst colors = [\n  '#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', '#FFEAA7',\n  '#DDA0DD', '#98D8C8', '#F7DC6F', '#BB8FCE', '#85C1E9'\n];\n\nexport function Demo() {\n  const [selectedColor, setSelectedColor] = useState<string>('#FF6B6B');\n\n  return (\n    <Flex direction=\"column\" gap={16} p={16} style={{ maxWidth: 400 }}>\n      <Text fw=\"semibold\" size=\"md\">Basic Color Swatches</Text>\n      \n      <Flex direction=\"column\" gap={8}>\n        <Text size=\"sm\">Click to select a color:</Text>\n        <Flex direction=\"row\" gap={8} wrap=\"wrap\">\n          {colors.map(color => (\n            <ColorSwatch\n              key={color}\n              color={color}\n              size={40}\n              selected={selectedColor === color}\n              onPress={() => setSelectedColor(color)}\n            />\n          ))}\n        </Flex>\n        <Text size=\"xs\" c=\"secondary\">\n          Selected: {selectedColor}\n        </Text>\n      </Flex>\n\n      <Flex direction=\"column\" gap={8}>\n        <Text size=\"sm\">Different sizes:</Text>\n        <Flex direction=\"row\" gap={8} align=\"center\">\n          <ColorSwatch color=\"#FF6B6B\" size={24} />\n          <ColorSwatch color=\"#4ECDC4\" size={32} />\n          <ColorSwatch color=\"#45B7D1\" size={48} />\n          <ColorSwatch color=\"#96CEB4\" size={64} />\n        </Flex>\n      </Flex>\n\n      <Flex direction=\"column\" gap={8}>\n        <Text size=\"sm\">Without borders:</Text>\n        <Flex direction=\"row\" gap={8}>\n          {colors.slice(0, 5).map(color => (\n            <ColorSwatch\n              key={color}\n              color={color}\n              size={32}\n              showBorder={false}\n            />\n          ))}\n        </Flex>\n      </Flex>\n\n      <Flex direction=\"column\" gap={8}>\n        <Text size=\"sm\">Disabled state:</Text>\n        <Flex direction=\"row\" gap={8}>\n          {colors.slice(0, 3).map(color => (\n            <ColorSwatch\n              key={color}\n              color={color}\n              size={32}\n              disabled\n            />\n          ))}\n        </Flex>\n      </Flex>\n    </Flex>\n  );\n}",hash:"1abbb6e8ea7b287ebf2549c0b223b66e828c457c73c7bd4c3bc3a650d29c98c3",importPath:"../../../../packages/ui/src/components/ColorSwatch/demos/basic",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/ColorSwatch/demos/basic/index.tsx"},"ColorSwatch.palette":{code:"import React, { useState } from 'react';\nimport { Flex, Text, ColorSwatch } from '@plocks/ui';\n\nexport function Demo() {\n  const [selectedColor, setSelectedColor] = useState<string>('#E74C3C');\n\n  const colorPalettes = {\n    'Material Colors': [\n      '#F44336', '#E91E63', '#9C27B0', '#673AB7', '#3F51B5',\n      '#2196F3', '#03A9F4', '#00BCD4', '#009688', '#4CAF50',\n      '#8BC34A', '#CDDC39', '#FFEB3B', '#FFC107', '#FF9800',\n      '#FF5722', '#795548', '#9E9E9E', '#607D8B', '#000000'\n    ],\n    'Pastel Colors': [\n      '#FFB3BA', '#FFDFBA', '#FFFFBA', '#BAFFC9', '#BAE1FF',\n      '#C5B3FF', '#FFB3E6', '#FFD1DC', '#E6E6FA', '#F0E68C'\n    ],\n    'Dark Colors': [\n      '#2C3E50', '#34495E', '#7F8C8D', '#95A5A6', '#BDC3C7',\n      '#1ABC9C', '#16A085', '#27AE60', '#229954', '#E74C3C'\n    ]\n  };\n\n  return (\n    <Flex direction=\"column\" gap={20} p={16} style={{ maxWidth: 600 }}>\n      <Text fw=\"semibold\" size=\"md\">Color Palette Builder</Text>\n      \n      <Flex direction=\"column\" gap={8}>\n        <Text size=\"sm\">Selected Color: {selectedColor}</Text>\n        <ColorSwatch \n          color={selectedColor} \n          size={60} \n          borderRadius={8}\n          showCheckmark={false}\n        />\n      </Flex>\n\n      {Object.entries(colorPalettes).map(([paletteName, colors]) => (\n        <Flex key={paletteName} direction=\"column\" gap={8}>\n          <Text fw=\"medium\" size=\"sm\">{paletteName}</Text>\n          <Flex direction=\"row\" gap={6} wrap=\"wrap\">\n            {colors.map(color => (\n              <ColorSwatch\n                key={color}\n                color={color}\n                size={32}\n                selected={selectedColor === color}\n                onPress={() => setSelectedColor(color)}\n                borderRadius={paletteName === 'Pastel Colors' ? 16 : 4}\n              />\n            ))}\n          </Flex>\n        </Flex>\n      ))}\n\n      <Flex direction=\"column\" gap={8}>\n        <Text fw=\"medium\" size=\"sm\">Custom Styles Examples</Text>\n        <Flex direction=\"row\" gap={12} wrap=\"wrap\">\n          <Flex direction=\"column\" gap={4} align=\"center\">\n            <ColorSwatch \n              color={selectedColor} \n              size={40} \n              borderRadius={20}\n              borderWidth={3}\n              borderColor=\"#FFD700\"\n            />\n            <Text size=\"xs\">Round Gold</Text>\n          </Flex>\n\n          <Flex direction=\"column\" gap={4} align=\"center\">\n            <ColorSwatch \n              color={selectedColor} \n              size={40} \n              showBorder={false}\n              showCheckmark={false}\n            />\n            <Text size=\"xs\">No Border</Text>\n          </Flex>\n\n          <Flex direction=\"column\" gap={4} align=\"center\">\n            <ColorSwatch \n              color={selectedColor} \n              size={40} \n              borderRadius={0}\n              checkmarkColor=\"#FFD700\"\n            />\n            <Text size=\"xs\">Square</Text>\n          </Flex>\n        </Flex>\n      </Flex>\n    </Flex>\n  );\n}",hash:"155daab159a65cfbebedf0da51df791b41bab420d0f859500393a66e2ebd5942",importPath:"../../../../packages/ui/src/components/ColorSwatch/demos/palette",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/ColorSwatch/demos/palette/index.tsx"}}},3574,[]);
__d(function(t,n,e,o,a,r,s){a.exports={"ComboChart.basic":{code:"import { ComboChart } from '@plocks/charts';\n\nimport { LAYERS } from './data';\n\nexport function Demo() {\n\treturn (\n\t\t<ComboChart\n\t\t\ttitle=\"Revenue vs. active users\"\n\t\t\tsubtitle=\"First half of FY25\"\n\t\t\th={340}\n\t\t\tlayers={LAYERS}\n\t\t\tenableCrosshair\n\t\t\tmultiTooltip\n\t\t\tliveTooltip\n\t\t\txAxis={{\n\t\t\t\tshow: true,\n\t\t\t\ttitle: 'Month',\n\t\t\t\tlabelFormatter: (value) => `M${value}`,\n\t\t\t}}\n\t\t\tyAxis={{\n\t\t\t\tshow: true,\n\t\t\t\ttitle: 'Revenue (USD thousands)',\n\t\t\t\tlabelFormatter: (value) => `$${value}`,\n\t\t\t}}\n\t\t\tyAxisRight={{\n\t\t\t\tshow: true,\n\t\t\t\ttitle: 'Active users (thousands)',\n\t\t\t\tlabelFormatter: (value) => `${value}k`,\n\t\t\t}}\n\t\t\tyDomain={[0, 650]}\n\t\t\tyDomainRight={[80, 200]}\n\t\t\tgrid={{ show: true, style: 'dashed' }}\n\t\t\tlegend={{ show: true, position: 'bottom' }}\n\t\t/>\n\t);\n}\n",hash:"a84a9633c01f33b8e46dda652a078e12163e38b3a674527238411cd370bc777d",importPath:"../../../../packages/charts/src/components/ComboChart/demos/basic",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/charts/src/components/ComboChart/demos/basic/index.tsx",files:[{name:"index.tsx",code:"import { ComboChart } from '@plocks/charts';\n\nimport { LAYERS } from './data';\n\nexport function Demo() {\n\treturn (\n\t\t<ComboChart\n\t\t\ttitle=\"Revenue vs. active users\"\n\t\t\tsubtitle=\"First half of FY25\"\n\t\t\th={340}\n\t\t\tlayers={LAYERS}\n\t\t\tenableCrosshair\n\t\t\tmultiTooltip\n\t\t\tliveTooltip\n\t\t\txAxis={{\n\t\t\t\tshow: true,\n\t\t\t\ttitle: 'Month',\n\t\t\t\tlabelFormatter: (value) => `M${value}`,\n\t\t\t}}\n\t\t\tyAxis={{\n\t\t\t\tshow: true,\n\t\t\t\ttitle: 'Revenue (USD thousands)',\n\t\t\t\tlabelFormatter: (value) => `$${value}`,\n\t\t\t}}\n\t\t\tyAxisRight={{\n\t\t\t\tshow: true,\n\t\t\t\ttitle: 'Active users (thousands)',\n\t\t\t\tlabelFormatter: (value) => `${value}k`,\n\t\t\t}}\n\t\t\tyDomain={[0, 650]}\n\t\t\tyDomainRight={[80, 200]}\n\t\t\tgrid={{ show: true, style: 'dashed' }}\n\t\t\tlegend={{ show: true, position: 'bottom' }}\n\t\t/>\n\t);\n}\n",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/charts/src/components/ComboChart/demos/basic/index.tsx"},{name:"data.ts",code:"export const LAYERS = [\n\t{\n\t\ttype: 'bar' as const,\n\t\tid: 'revenue',\n\t\tname: 'Monthly revenue',\n\t\tdata: [\n\t\t\t{ x: 1, y: 420 },\n\t\t\t{ x: 2, y: 455 },\n\t\t\t{ x: 3, y: 508 },\n\t\t\t{ x: 4, y: 480 },\n\t\t\t{ x: 5, y: 532 },\n\t\t\t{ x: 6, y: 575 },\n\t\t],\n\t\topacity: 0.85,\n\t},\n\t{\n\t\ttype: 'line' as const,\n\t\tid: 'active-users',\n\t\tname: 'Active users',\n\t\ttargetAxis: 'right' as const,\n\t\tdata: [\n\t\t\t{ x: 1, y: 110 },\n\t\t\t{ x: 2, y: 134 },\n\t\t\t{ x: 3, y: 149 },\n\t\t\t{ x: 4, y: 158 },\n\t\t\t{ x: 5, y: 166 },\n\t\t\t{ x: 6, y: 172 },\n\t\t],\n\t\tthickness: 3,\n\t\tshowPoints: true,\n\t\tpointSize: 6,\n\t},\n];",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/charts/src/components/ComboChart/demos/basic/data.ts"}]},"ComboChart.brush":{code:"import { ComboChart } from '@plocks/charts';\n\nimport { LAYERS } from './data';\n\nexport function Demo() {\n  return (\n    <ComboChart\n      h={340}\n      layers={LAYERS}\n      withBrush\n      brushProps={{ start: 37, end: 60 }}\n      xAxis={{ show: true, labelFormatter: (value) => `M${value}` }}\n      yAxis={{ show: true }}\n    />\n  );\n}\n",hash:"3468d6d7c35ff6d8404e4a0cc36fb9008852425777481bb44456a9af40294410",importPath:"../../../../packages/charts/src/components/ComboChart/demos/brush",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/charts/src/components/ComboChart/demos/brush/index.tsx",files:[{name:"index.tsx",code:"import { ComboChart } from '@plocks/charts';\n\nimport { LAYERS } from './data';\n\nexport function Demo() {\n  return (\n    <ComboChart\n      h={340}\n      layers={LAYERS}\n      withBrush\n      brushProps={{ start: 37, end: 60 }}\n      xAxis={{ show: true, labelFormatter: (value) => `M${value}` }}\n      yAxis={{ show: true }}\n    />\n  );\n}\n",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/charts/src/components/ComboChart/demos/brush/index.tsx"},{name:"data.ts",code:"// Five years of monthly orders with a 6-month moving average.\nconst ORDERS = Array.from({ length: 60 }, (_, month) =>\n  Math.round(300 + month * 6 + 70 * Math.sin((month / 12) * Math.PI * 2) + 25 * Math.sin(month * 2.1)),\n);\n\nconst movingAverage = (values: number[], window: number) =>\n  values.map((_, index) => {\n    const slice = values.slice(Math.max(0, index - window + 1), index + 1);\n    return Math.round(slice.reduce((sum, value) => sum + value, 0) / slice.length);\n  });\n\nexport const LAYERS = [\n  {\n    type: 'bar' as const,\n    id: 'orders',\n    name: 'Orders',\n    data: ORDERS.map((y, index) => ({ x: index + 1, y })),\n  },\n  {\n    type: 'line' as const,\n    id: 'average',\n    name: '6-month average',\n    data: movingAverage(ORDERS, 6).map((y, index) => ({ x: index + 1, y })),\n  },\n];",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/charts/src/components/ComboChart/demos/brush/data.ts"}]},"ComboChart.referenceMarks":{code:"import { ComboChart } from '@plocks/charts';\n\nimport { LAYERS } from './data';\n\nexport function Demo() {\n  return (\n    <ComboChart\n      title=\"Monthly orders\"\n      h={320}\n      layers={LAYERS}\n      yDomain={[0, 700]}\n      referenceAreas={[{ x1: 4.5, x2: 6.5, color: '#10b981', label: 'Promo' }]}\n      referenceLines={[{ y: 500, label: 'Target 500', color: '#f59e0b', dashed: true }]}\n      referenceDots={[{ x: 12, y: 640, r: 6, color: '#10b981', label: 'Record' }]}\n      xAxis={{ show: true, labelFormatter: (value) => `M${value}` }}\n      yAxis={{ show: true }}\n      legend={{ show: true, position: 'bottom' }}\n    />\n  );\n}\n",hash:"2c638bd15fe70512e15ef62dddc8b94006115744b7430b50861cf3c6dafc48eb",importPath:"../../../../packages/charts/src/components/ComboChart/demos/referenceMarks",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/charts/src/components/ComboChart/demos/referenceMarks/index.tsx",files:[{name:"index.tsx",code:"import { ComboChart } from '@plocks/charts';\n\nimport { LAYERS } from './data';\n\nexport function Demo() {\n  return (\n    <ComboChart\n      title=\"Monthly orders\"\n      h={320}\n      layers={LAYERS}\n      yDomain={[0, 700]}\n      referenceAreas={[{ x1: 4.5, x2: 6.5, color: '#10b981', label: 'Promo' }]}\n      referenceLines={[{ y: 500, label: 'Target 500', color: '#f59e0b', dashed: true }]}\n      referenceDots={[{ x: 12, y: 640, r: 6, color: '#10b981', label: 'Record' }]}\n      xAxis={{ show: true, labelFormatter: (value) => `M${value}` }}\n      yAxis={{ show: true }}\n      legend={{ show: true, position: 'bottom' }}\n    />\n  );\n}\n",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/charts/src/components/ComboChart/demos/referenceMarks/index.tsx"},{name:"data.ts",code:"const ORDERS = [320, 340, 365, 410, 520, 560, 480, 455, 470, 510, 590, 640];\n\nconst movingAverage = (values: number[], window: number) =>\n  values.map((_, index) => {\n    const slice = values.slice(Math.max(0, index - window + 1), index + 1);\n    return Math.round(slice.reduce((sum, value) => sum + value, 0) / slice.length);\n  });\n\nexport const LAYERS = [\n  {\n    type: 'bar' as const,\n    id: 'orders',\n    name: 'Orders',\n    data: ORDERS.map((y, index) => ({ x: index + 1, y })),\n  },\n  {\n    type: 'line' as const,\n    id: 'average',\n    name: '3-month average',\n    showPoints: false,\n    data: movingAverage(ORDERS, 3).map((y, index) => ({ x: index + 1, y })),\n  },\n];",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/charts/src/components/ComboChart/demos/referenceMarks/data.ts"}]}}},3575,[]);
