__d(function(n,e,t,a,o,s,i){o.exports={"Pagination.advanced":{code:"import { useState } from 'react';\n\nimport { Block, Pagination, Text } from '@plocks/ui';\n\nexport function Demo() {\n  const [page1, setPage1] = useState(10);\n  const [page2, setPage2] = useState(15);\n  const [page3, setPage3] = useState(25);\n\n  return (\n    <Block>\n      <Block>\n        <Pagination\n          value={page1}\n          total={30}\n          onChange={setPage1}\n          showFirst\n          showPrevNext\n          siblings={2}\n          boundaries={2}\n        />\n        <Text size=\"xs\" c=\"secondary\">\n          Includes first and last buttons. Page {page1} of 30.\n        </Text>\n      </Block>\n\n      <Block>\n        <Pagination\n          value={page2}\n          total={40}\n          onChange={setPage2}\n          showPrevNext\n          siblings={1}\n          boundaries={1}\n        />\n        <Text size=\"xs\" c=\"secondary\">\n          Minimal navigation with prev/next only. Page {page2} of 40.\n        </Text>\n      </Block>\n\n      <Block>\n        <Pagination\n          value={page3}\n          total={50}\n          onChange={setPage3}\n          showPrevNext\n          siblings={0}\n          boundaries={1}\n          size=\"sm\"\n        />\n        <Text size=\"xs\" c=\"secondary\">\n          Compact layout with tight siblings. Page {page3} of 50.\n        </Text>\n      </Block>\n    </Block>\n  );\n}\n\n\n",hash:"fc510e7c2b2c0f14af2d4ae33b7263ae1faf97c00293dc2c174537e4a6ecb7b5",importPath:"../../../../packages/ui/src/components/Pagination/demos/advanced",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/Pagination/demos/advanced/index.tsx"},"Pagination.basic":{code:"import { useState } from 'react';\n\nimport { Block, Pagination, Text } from '@plocks/ui';\n\nexport function Demo() {\n  const [currentPage, setCurrentPage] = useState(1);\n  const totalPages = 10;\n\n  return (\n    <Block>\n      <Pagination value={currentPage} total={totalPages} onChange={setCurrentPage} />\n      <Text size=\"xs\" c=\"secondary\">\n        Page {currentPage} of {totalPages}\n      </Text>\n    </Block>\n  );\n}\n\n\n",hash:"c58c7fcd76b785a8356888018c7248986f17bb1e2e2becec4212fea30565cfc9",importPath:"../../../../packages/ui/src/components/Pagination/demos/basic",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/Pagination/demos/basic/index.tsx"},"Pagination.size-changer":{code:"import { useState } from 'react';\n\nimport { Block, Pagination, Text } from '@plocks/ui';\n\nexport function Demo() {\n  const totalItems = 248;\n  const [pageSize, setPageSize] = useState(10);\n  const [current, setCurrent] = useState(1);\n\n  const total = Math.max(1, Math.ceil(totalItems / pageSize));\n\n  return (\n    <Block>\n      <Pagination\n        value={current}\n        total={total}\n        onChange={setCurrent}\n        showTotal\n        totalItems={totalItems}\n        pageSize={pageSize}\n        showSizeChanger\n        pageSizeOptions={[10, 20, 50, 100]}\n        onPageSizeChange={(size) => {\n          setPageSize(size);\n          setCurrent(1);\n        }}\n      />\n      <Text size=\"xs\" c=\"secondary\">\n        Page {current} of {total} \xb7 {pageSize} rows per page\n      </Text>\n    </Block>\n  );\n}\n",hash:"85f8b05a46f17ab06025cd9b2b9b2fb46dc387cf61a669eaa3a671accecc5852",importPath:"../../../../packages/ui/src/components/Pagination/demos/size-changer",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/Pagination/demos/size-changer/index.tsx"},"Pagination.sizes":{code:"import { useState } from 'react';\nimport { Block, Pagination, Text } from '@plocks/ui';\n\nconst SIZES = ['xs', 'sm', 'md', 'lg', 'xl', '2xl', '3xl'] as const;\n\nexport function Demo() {\n  const [page, setPage] = useState(3);\n\n  return (\n    <Block>\n      {SIZES.map((size) => (\n        <Block key={size}>\n          <Text variant=\"small\" c=\"secondary\">{size}</Text>\n          <Pagination value={page} total={8} onChange={setPage} size={size} />\n        </Block>\n      ))}\n    </Block>\n  );\n}\n",hash:"377b401aa8dcc160c0efdf67ffbc9b7b623c289b99d8cffcc48b7f3fb7a882b5",importPath:"../../../../packages/ui/src/components/Pagination/demos/sizes",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/Pagination/demos/sizes/index.tsx"},"Pagination.variants":{code:"import { useState } from 'react';\n\nimport { Block, Pagination, Text } from '@plocks/ui';\n\nexport function Demo() {\n  const [defaultPage, setDefaultPage] = useState(5);\n  const [outlinePage, setOutlinePage] = useState(5);\n  const [subtlePage, setSubtlePage] = useState(5);\n\n  return (\n    <Block>\n      <Block>\n        <Pagination value={defaultPage} total={15} onChange={setDefaultPage} variant=\"default\" />\n        <Text size=\"xs\" c=\"secondary\">\n          Default variant keeps the control fully filled. Page {defaultPage} of 15.\n        </Text>\n      </Block>\n\n      <Block>\n        <Pagination value={outlinePage} total={15} onChange={setOutlinePage} variant=\"outline\" />\n        <Text size=\"xs\" c=\"secondary\">\n          Outline keeps the surface quiet while the active page gets a stroke. Page {outlinePage} of 15.\n        </Text>\n      </Block>\n\n      <Block>\n        <Pagination value={subtlePage} total={15} onChange={setSubtlePage} variant=\"subtle\" />\n        <Text size=\"xs\" c=\"secondary\">\n          Subtle removes backgrounds for tinted surfaces. Page {subtlePage} of 15.\n        </Text>\n      </Block>\n    </Block>\n  );\n}\n\n\n",hash:"e0260e58ad5c68cfdfdfe69153b8bdf06af837e5ce3c242ffccfebf92c32023f",importPath:"../../../../packages/ui/src/components/Pagination/demos/variants",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/Pagination/demos/variants/index.tsx"}}},3641,[]);
