__d(function(e,n,t,a,o,i,m){o.exports={"ShimmerText.basic":{code:"import { Block, ShimmerText } from '@plocks/ui';\n\nexport function Demo() {\n  return (\n    <Block align=\"flex-start\">\n      <ShimmerText size=\"xl\" fw=\"bold\">\n        Weekly highlights go live\n      </ShimmerText>\n      <ShimmerText>\n        New arrivals shimmer into view every Friday at noon.\n      </ShimmerText>\n    </Block>\n  );\n}",hash:"6b87ecef6f468e94e0acee655fc8f2bf74335adef78c85b208cf144e64408eff",importPath:"../../../../packages/ui/src/components/ShimmerText/demos/basic",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/ShimmerText/demos/basic/index.tsx"},"ShimmerText.controls":{code:"import { useState } from 'react';\nimport { Block, Row, ShimmerText, Slider, Switch, Text } from '@plocks/ui';\n\nconst MIN_SPREAD = 1;\nconst MAX_SPREAD = 4;\nconst SPREAD_STEP = 0.1;\n\nexport function Demo() {\n  const [spread, setSpread] = useState(2);\n  const [repeat, setRepeat] = useState(true);\n  const [once, setOnce] = useState(false);\n\n  const handleRepeatChange = (value: boolean) => {\n    setRepeat(value);\n    if (value) {\n      setOnce(false);\n    }\n  };\n\n  const handleOnceChange = (value: boolean) => {\n    setOnce(value);\n    if (value) {\n      setRepeat(false);\n    }\n  };\n\n  return (\n    <Block align=\"flex-start\" fullWidth>\n      <ShimmerText\n        spread={spread}\n        repeat={repeat}\n        once={once}\n        repeatDelay={0.6}\n        duration={1.6}\n        shimmerColor=\"#38bdf8\"\n        fw=\"bold\"\n        size=\"lg\"\n      >\n        Interactive shimmer headline\n      </ShimmerText>\n\n      <Block w=\"100%\">\n        <Text variant=\"small\" fw=\"medium\">\n          Spread: {spread.toFixed(1)}\n        </Text>\n        <Slider\n          value={spread}\n          onChange={setSpread}\n          min={MIN_SPREAD}\n          max={MAX_SPREAD}\n          step={SPREAD_STEP}\n        />\n      </Block>\n\n      <Block w=\"100%\">\n        <Row align=\"center\" justify=\"space-between\">\n          <Text variant=\"small\">Repeat animation</Text>\n          <Switch checked={repeat} onChange={handleRepeatChange} />\n        </Row>\n        <Row align=\"center\" justify=\"space-between\">\n          <Text variant=\"small\">Run once</Text>\n          <Switch checked={once} onChange={handleOnceChange} />\n        </Row>\n      </Block>\n    </Block>\n  );\n}\n",hash:"b393845c7a9f90fc38128d33cdcc930b0e1dd5315275e9ce0ae7386b18f15c64",importPath:"../../../../packages/ui/src/components/ShimmerText/demos/controls",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/ShimmerText/demos/controls/index.tsx"},"ShimmerText.customization":{code:"import { Block, ShimmerText } from '@plocks/ui';\n\nexport function Demo() {\n  return (\n    <Block align=\"flex-start\">\n      <ShimmerText shimmerColor=\"#facc15\" spread={3} fw=\"bold\" size=\"xl\">\n        Golden spotlight offer\n      </ShimmerText>\n      <ShimmerText\n        c=\"#475569\"\n        shimmerColor=\"#38bdf8\"\n        spread={1.2}\n        duration={1.2}\n        repeatDelay={0.2}\n      >\n        Fast pulse notification\n      </ShimmerText>\n      <ShimmerText direction=\"rtl\" repeatDelay={0.8}>\n        Shimmer sweeps from right to left\n      </ShimmerText>\n      <ShimmerText once repeat={false} delay={0.5}>\n        Single pass announcement\n      </ShimmerText>\n    </Block>\n  );\n}\n",hash:"a39a94cc94074eda442f763d56080a15241d99598f74aedc812ac38f3787e903",importPath:"../../../../packages/ui/src/components/ShimmerText/demos/customization",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/ShimmerText/demos/customization/index.tsx"},"ShimmerText.variants":{code:"import { Column, ShimmerText, Text } from '@plocks/ui';\n\nconst variants = ['h3', 'p', 'small'] as const;\n\nexport function Demo() {\n  return (\n    <Column gap=\"md\">\n      {variants.map(variant => (\n        <Column key={variant} gap=\"xs\">\n          <Text size=\"xs\" c=\"secondary\">{variant}</Text>\n          <ShimmerText variant={variant}>New arrivals this week</ShimmerText>\n        </Column>\n      ))}\n    </Column>\n  );\n}\n",hash:"68362c559b723e6e27489db262f4907422552e38e80b6b887b1ab2b67df1e239",importPath:"../../../../packages/ui/src/components/ShimmerText/demos/variants",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/ui/src/components/ShimmerText/demos/variants/index.tsx"}}},3665,[]);
