__d(function(e,o,n,t,s,i,r){s.exports={"Video.basic":{code:"import { useRef } from 'react';\nimport { Asset } from 'expo-asset';\nimport { Block, Button, Row } from '@plocks/ui';\nimport { Video } from '@plocks/media';\nimport type { VideoRef } from '@plocks/media';\n\n// `source.url` takes a URL, so resolve the bundled clip to one. `Image.resolveAssetSource`\n// is native-only, whereas expo-asset works on web too.\nconst SOURCE = {\n  url: Asset.fromModule(require('../../../../assets/video/demo-clip.mp4')).uri,\n} as const;\n\nexport function Demo() {\n  const videoRef = useRef<VideoRef>(null);\n\n  return (\n    <Block fullWidth>\n      <Video ref={videoRef} source={SOURCE} />\n      <Row gap=\"sm\">\n        <Button size=\"xs\" variant=\"outline\" onPress={() => videoRef.current?.play()}>\n          Play\n        </Button>\n        <Button size=\"xs\" variant=\"outline\" onPress={() => videoRef.current?.pause()}>\n          Pause\n        </Button>\n        <Button size=\"xs\" variant=\"outline\" onPress={() => videoRef.current?.seek(4)}>\n          Skip to 4s\n        </Button>\n      </Row>\n    </Block>\n  );\n}\n",hash:"4f8f66a64b06f19813f922812bd188e57bba8182162d0ad038eb51e2a76a7b3c",importPath:"../../../../packages/media/src/components/Video/demos/basic",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/media/src/components/Video/demos/basic/index.tsx"},"Video.timeline":{code:"import { useState } from 'react';\nimport { Asset } from 'expo-asset';\nimport { Block, Text } from '@plocks/ui';\nimport { Video } from '@plocks/media';\nimport type { VideoTimelineEvent } from '@plocks/media';\n\n// `source.url` takes a URL, so resolve the bundled clip to one. `Image.resolveAssetSource`\n// is native-only, whereas expo-asset works on web too.\nconst SOURCE = {\n  url: Asset.fromModule(require('../../../../assets/video/demo-clip.mp4')).uri,\n} as const;\n\nexport function Demo() {\n  const [log, setLog] = useState<string[]>([]);\n\n  const timeline: VideoTimelineEvent[] = [\n    {\n      id: 'intro',\n      time: 2,\n      type: 'chapter',\n      data: { title: 'Introduction' },\n      callback: () => setLog((entries) => [...entries, 'Reached introduction at 2s']),\n    },\n    {\n      id: 'main-content',\n      time: 5,\n      type: 'chapter',\n      data: { title: 'Main content' },\n      callback: () => setLog((entries) => [...entries, 'Reached main content at 5s']),\n    },\n  ];\n\n  return (\n    <Block fullWidth>\n      <Video source={SOURCE} timeline={timeline} />\n      {log.map((entry, index) => (\n        <Text key={`${entry}-${index}`} size=\"xs\">\n          {entry}\n        </Text>\n      ))}\n    </Block>\n  );\n}\n",hash:"d824edb5aa3dcab97ed58e2b0fcf6d28cd87e2e5848944e47cb1134252372fe1",importPath:"../../../../packages/media/src/components/Video/demos/timeline",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/media/src/components/Video/demos/timeline/index.tsx"},"Video.youtube":{code:"import { Block } from '@plocks/ui';\nimport { Video } from '@plocks/media';\n\nexport function Demo() {\n  return (\n    <Block fullWidth>\n      <Video source={{ youtube: 'dQw4w9WgXcQ' }} />\n    </Block>\n  );\n}\n",hash:"80f42db99fe9f492a979490c6721a1b131ac2350bd591d217c44d61cdda87f7c",importPath:"../../../../packages/media/src/components/Video/demos/youtube",githubUrl:"https://github.com/platform-blocks/plocks/blob/main/packages/media/src/components/Video/demos/youtube/index.tsx"}}},3697,[]);
